 public function __construct(string $appName,IRequest $request,private ProjectMapper $mapper,private CustomerMapper $customers,private IUserSession $users,private IURLGenerator $url,private FolderService $folders,private NumberService $numbers,private PermissionService $permissions,private ActivityService $activities,private IDBConnection $db,private ProjectPhaseService $projectPhases){parent::__construct($appName,$request);}
 #[NoAdminRequired]
 public function save(?int $id,int $customerId,?string $projectNo,string $title,string $status='Anfrage',?string $startDate=null,?string $dueDate=null,?string $description=null):RedirectResponse{$this->permissions->assertProjectManager();
  $title=trim($title);if($customerId<=0||$title==='')throw new \InvalidArgumentException('Kunde und Titel sind Pflicht.');$phase=$this->projectPhases->findByName($status);if(!$phase){$active=$this->projectPhases->names(true);$status=$active[0]??'Anfrage';}
  $now=new \DateTime();$p=$id!==null?$this->mapper->find($id):new Project();$projectNo=$id===null?$this->numbers->next('project'):$p->getProjectNo();$p->setCustomerId($customerId);$p->setProjectNo($projectNo);$p->setTitle($title);$p->setStatus($status);$p->setStartDate($this->d($startDate));$p->setDueDate($this->d($dueDate));$p->setDescription($this->n($description));$p->setUpdatedAt($now);
  $customer=$this->customers->find($customerId);$path=$customer->getFolderPath() ?: $this->folders->ensureCustomerFolder((string)$customer->getCustomerNo(),$customer->getName());$p->setFolderPath($this->folders->ensureProjectFolder($path,$projectNo,$title));
  if($id===null){$p->setCreatedAt($now);$p->setCreatedBy($this->users->getUser()?->getUID()??'system');$this->mapper->insert($p);$this->activities->record('project',$p->getId(),'created','Projekt erstellt',$projectNo.' · '.$title,$customerId,$p->getId());}else{$this->mapper->update($p);$this->activities->record('project',$p->getId(),'updated','Projekt geändert',$projectNo.' · '.$title,$customerId,$p->getId());}if(!empty($phase['freeze_calculation']))$this->freezeCalculation((int)$p->getId());return new RedirectResponse($this->url->linkToRoute('reinhardterp.page.projectDetail',['id'=>$p->getId()]));
 }
 #[NoAdminRequired] public function archive(int $id):RedirectResponse{$this->permissions->assertProjectManager();$p=$this->mapper->find($id);$p->setIsArchived(true);$p->setUpdatedAt(new \DateTime());$this->mapper->update($p);$this->activities->record('project',$id,'archived','Projekt archiviert',$p->getProjectNo().' · '.$p->getTitle(),$p->getCustomerId(),$id);return new RedirectResponse($this->url->linkToRoute('reinhardterp.page.projects'));}
 #[NoAdminRequired] public function restore(int $id):RedirectResponse{$this->permissions->assertProjectManager();$p=$this->mapper->find($id);$p->setIsArchived(false);$p->setUpdatedAt(new \DateTime());$this->mapper->update($p);$this->activities->record('project',$id,'restored','Projekt wiederhergestellt',$p->getProjectNo().' · '.$p->getTitle(),$p->getCustomerId(),$id);return new RedirectResponse($this->url->linkToRoute('reinhardterp.page.projects',['view'=>'archive']));}
 #[NoAdminRequired] public function updateStatus(int $id,string $status):RedirectResponse{$this->permissions->assertProjectManager();$phase=$this->projectPhases->findByName($status);if(!$phase||empty($phase['active']))throw new \InvalidArgumentException('Ungültige oder inaktive Projektphase.');$p=$this->mapper->find($id);$old=(string)$p->getStatus();if(!empty($phase['freeze_calculation']))$this->freezeCalculation($id);$p->setStatus($status);$p->setUpdatedAt(new \DateTime());$this->mapper->update($p);$this->activities->record('project',$id,'status_changed','Status geändert',$old.' → '.$status,$p->getCustomerId(),$id);return new RedirectResponse($this->url->linkToRoute('reinhardterp.page.projectDetail',['id'=>$id]));}

 #[NoAdminRequired] public function saveAssignments(int $id):RedirectResponse{
  $this->permissions->assertProjectManager();$project=$this->mapper->find($id);
  $selected=array_values(array_unique(array_filter(array_map('strval',(array)$this->request->getParam('projectUsers',[])),static fn(string $v):bool=>$v!=='')));
  $folders=(array)$this->request->getParam('folders',[]);
  $del=$this->db->getQueryBuilder();$del->delete('re_erp_project_users')->where($del->expr()->eq('project_id',$del->createNamedParameter($id)))->executeStatement();
  foreach($selected as $uid){$allowed=array_values(array_intersect(PermissionService::PROJECT_FOLDERS,array_map('strval',(array)($folders[$uid]??PermissionService::EMPLOYEE_DEFAULT_FOLDERS))));if($allowed===[])$allowed=PermissionService::EMPLOYEE_DEFAULT_FOLDERS;$q=$this->db->getQueryBuilder();$q->insert('re_erp_project_users')->values(['project_id'=>$q->createNamedParameter($id),'user_id'=>$q->createNamedParameter($uid),'role'=>$q->createNamedParameter('Mitarbeiter'),'folder_permissions'=>$q->createNamedParameter(json_encode($allowed,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))])->executeStatement();}
  $this->activities->record('project',$id,'permissions_changed','Projektfreigaben geändert',count($selected).' Mitarbeiter freigegeben',$project->getCustomerId(),$id);
  return new RedirectResponse($this->url->linkToRoute('reinhardterp.page.projectDetail',['id'=>$id]).'#permissions');
 }


 #[NoAdminRequired] public function saveSupplierCockpit(int $id,?int $rowId=null,int $supplierId=0,?string $trade=null,?string $purchaseNo=null,string $confirmationStatus='open',?string $confirmationNo=null,?int $expectedWeek=null,string $receiptStatus='open',int $mountingRelevant=0,?int $confirmationDocumentId=null,?int $deliveryDocumentId=null,?string $notes=null,?int $materialId=null,?float $orderedQty=null,?float $unitCost=null,array $materialIds=[],array $orderedQtys=[],array $unitCosts=[]):RedirectResponse{
  $this->permissions->assertProjectManager();$project=$this->mapper->find($id);
  if($supplierId<=0)throw new \InvalidArgumentException('Bitte einen Lieferanten auswählen.');
  $q=$this->db->getQueryBuilder();$q->select('id','name')->from('re_erp_suppliers')->where($q->expr()->eq('id',$q->createNamedParameter($supplierId)));$supplier=$q->executeQuery()->fetch();if(!$supplier)throw new \InvalidArgumentException('Lieferant nicht gefunden.');
  if(!in_array($confirmationStatus,['open','received'],true))$confirmationStatus='open';
  if(!in_array($receiptStatus,['open','partial','complete'],true))$receiptStatus='open';
  if($expectedWeek!==null&&($expectedWeek<1||$expectedWeek>53))$expectedWeek=null;
  $docIds=[];foreach([$confirmationDocumentId,$deliveryDocumentId] as $docId){if($docId){$dq=$this->db->getQueryBuilder();$dq->select('id')->from('re_erp_documents')->where($dq->expr()->eq('id',$dq->createNamedParameter($docId)))->andWhere($dq->expr()->eq('project_id',$dq->createNamedParameter($id)));if(!$dq->executeQuery()->fetchOne())throw new \InvalidArgumentException('Das ausgewählte Dokument gehört nicht zu diesem Projekt.');$docIds[]=$docId;}}
  $data=['project_id'=>$id,'supplier_id'=>$supplierId,'trade'=>$this->n($trade),'purchase_no'=>$this->n($purchaseNo),'confirmation_status'=>$confirmationStatus,'confirmation_no'=>$this->n($confirmationNo),'expected_week'=>$expectedWeek,'receipt_status'=>$receiptStatus,'mounting_relevant'=>$mountingRelevant?1:0,'confirmation_document_id'=>$confirmationDocumentId?:null,'delivery_document_id'=>$deliveryDocumentId?:null,'notes'=>$this->n($notes),'updated_at'=>date('Y-m-d H:i:s')];
  if($rowId){$check=$this->db->getQueryBuilder();$check->select('id')->from('re_erp_project_suppliers')->where($check->expr()->eq('id',$check->createNamedParameter($rowId)))->andWhere($check->expr()->eq('project_id',$check->createNamedParameter($id)));if(!$check->executeQuery()->fetchOne())throw new \InvalidArgumentException('Lieferantenzeile nicht gefunden.');$u=$this->db->getQueryBuilder();$u->update('re_erp_project_suppliers');foreach($data as $k=>$v)$u->set($k,$u->createNamedParameter($v));$u->where($u->expr()->eq('id',$u->createNamedParameter($rowId)))->executeStatement();$action='updated';}else{$data['created_by']=$this->users->getUser()?->getUID()??'system';$data['created_at']=date('Y-m-d H:i:s');$i=$this->db->getQueryBuilder();$i->insert('re_erp_project_suppliers');foreach($data as $k=>$v)$i->setValue($k,$i->createNamedParameter($v));$i->executeStatement();$rowId=(int)$this->db->lastInsertId('*PREFIX*re_erp_project_suppliers');$action='created';
   $newItems=[];if($materialId&&$orderedQty!==null&&$orderedQty>0)$newItems[]=[$materialId,$orderedQty,$unitCost];foreach($materialIds as $idx=>$mid){$mid=(int)$mid;$qty=isset($orderedQtys[$idx])?(float)$orderedQtys[$idx]:0;$uc=(isset($unitCosts[$idx])&&$unitCosts[$idx]!==''&&$unitCosts[$idx]!==null)?(float)$unitCosts[$idx]:null;if($mid>0&&$qty>0)$newItems[]=[$mid,$qty,$uc];}foreach($newItems as [$newMaterialId,$newOrderedQty,$newUnitCost]){$mq=$this->db->getQueryBuilder();$mq->select('id','purchase_price','supplier_id')->from('re_erp_materials')->where($mq->expr()->eq('id',$mq->createNamedParameter($newMaterialId)))->andWhere($mq->expr()->eq('active',$mq->createNamedParameter(1)));$mat=$mq->executeQuery()->fetch();if(!$mat)throw new \InvalidArgumentException('Material nicht gefunden.');if(!empty($mat['supplier_id'])&&(int)$mat['supplier_id']!==$supplierId)throw new \InvalidArgumentException('Das Material gehört nicht zum ausgewählten Lieferanten.');$cost=$newUnitCost!==null?max(0,$newUnitCost):(float)($mat['purchase_price']??0);$now=date('Y-m-d H:i:s');$pq=$this->db->getQueryBuilder();$pq->insert('re_erp_purchase_items')->values(['project_supplier_id'=>$pq->createNamedParameter($rowId),'material_id'=>$pq->createNamedParameter($newMaterialId),'ordered_qty'=>$pq->createNamedParameter($newOrderedQty),'received_qty'=>$pq->createNamedParameter(0),'unit_cost'=>$pq->createNamedParameter($cost),'created_at'=>$pq->createNamedParameter($now),'updated_at'=>$pq->createNamedParameter($now)])->executeStatement();}}
  foreach($docIds as $docId){$u=$this->db->getQueryBuilder();$u->update('re_erp_documents')->set('supplier_id',$u->createNamedParameter($supplierId))->set('updated_at',$u->createNamedParameter(date('Y-m-d H:i:s')))->where($u->expr()->eq('id',$u->createNamedParameter($docId)))->executeStatement();}
  $this->activities->record('project',$id,'supplier_'.$action,'Lieferantensteuerung geändert',(string)$supplier['name'].' · '.($data['purchase_no']??''),$project->getCustomerId(),$id);
  return new RedirectResponse($this->url->linkToRoute('reinhardterp.page.projectDetail',['id'=>$id]).'#suppliers');
 }
 #[NoAdminRequired] public function addPurchaseItem(int $id,int $rowId,int $materialId,float $orderedQty,?float $unitCost=null):RedirectResponse{
  $this->permissions->assertProjectManager();$project=$this->mapper->find($id);if($project->getIsArchived())throw new \InvalidArgumentException('Archivierte Projekte können nicht bebucht werden.');
  if($orderedQty<=0)throw new \InvalidArgumentException('Bestellmenge muss größer als 0 sein.');
  $q=$this->db->getQueryBuilder();$q->select('id','supplier_id')->from('re_erp_project_suppliers')->where($q->expr()->eq('id',$q->createNamedParameter($rowId)))->andWhere($q->expr()->eq('project_id',$q->createNamedParameter($id)));$ps=$q->executeQuery()->fetch();if(!$ps)throw new \InvalidArgumentException('Bestellung nicht gefunden.');
  $q=$this->db->getQueryBuilder();$q->select('id','purchase_price','supplier_id')->from('re_erp_materials')->where($q->expr()->eq('id',$q->createNamedParameter($materialId)))->andWhere($q->expr()->eq('active',$q->createNamedParameter(1)));$m=$q->executeQuery()->fetch();if(!$m)throw new \InvalidArgumentException('Material nicht gefunden.');if(!empty($m['supplier_id'])&&(int)$m['supplier_id']!==(int)$ps['supplier_id'])throw new \InvalidArgumentException('Das Material gehört nicht zum ausgewählten Lieferanten.');
  $cost=$unitCost!==null?max(0,$unitCost):(float)($m['purchase_price']??0);$now=date('Y-m-d H:i:s');$q=$this->db->getQueryBuilder();$q->insert('re_erp_purchase_items')->values(['project_supplier_id'=>$q->createNamedParameter($rowId),'material_id'=>$q->createNamedParameter($materialId),'ordered_qty'=>$q->createNamedParameter($orderedQty),'received_qty'=>$q->createNamedParameter(0),'unit_cost'=>$q->createNamedParameter($cost),'created_at'=>$q->createNamedParameter($now),'updated_at'=>$q->createNamedParameter($now)])->executeStatement();
  $this->activities->record('project',$id,'purchase_item_added','Bestellposition hinzugefügt','Material #'.$materialId.' · '.$orderedQty,$project->getCustomerId(),$id);return new RedirectResponse($this->url->linkToRoute('reinhardterp.page.projectDetail',['id'=>$id]).'#suppliers');
 }
 #[NoAdminRequired] public function receivePurchaseItem(int $id,int $itemId,float $quantity,string $destination='stock',?string $note=null):RedirectResponse{
  $this->permissions->assertProjectManager();$project=$this->mapper->find($id);if($project->getIsArchived())throw new \InvalidArgumentException('Auf archivierte Projekte kann kein Wareneingang gebucht werden.');if($quantity<=0)throw new \InvalidArgumentException('Liefermenge muss größer als 0 sein.');if(!in_array($destination,['stock','project'],true))$destination='stock';
  $q=$this->db->getQueryBuilder();$q->select('pi.*','ps.project_id','ps.purchase_no','m.stock_quantity','m.purchase_price','m.name AS material_name')->from('re_erp_purchase_items','pi')->leftJoin('pi','re_erp_project_suppliers','ps',$q->expr()->eq('ps.id','pi.project_supplier_id'))->leftJoin('pi','re_erp_materials','m',$q->expr()->eq('m.id','pi.material_id'))->where($q->expr()->eq('pi.id',$q->createNamedParameter($itemId)))->andWhere($q->expr()->eq('ps.project_id',$q->createNamedParameter($id)));$r=$q->executeQuery()->fetch();if(!$r)throw new \InvalidArgumentException('Bestellposition nicht gefunden.');
  $ordered=(float)$r['ordered_qty'];$received=(float)$r['received_qty'];$open=max(0,$ordered-$received);if($quantity>$open+0.0001)throw new \InvalidArgumentException('Liefermenge ist größer als die noch offene Menge.');$cost=$r['unit_cost']!==null?(float)$r['unit_cost']:(float)($r['purchase_price']??0);$now=date('Y-m-d H:i:s');$label=trim((string)$note);$prefix='Wareneingang Bestellung '.((string)($r['purchase_no']??'')?:'#'.$r['project_supplier_id']);$label=$label!==''?$prefix.' · '.$label:$prefix;
  $base=['material_id'=>(int)$r['material_id'],'customer_id'=>$project->getCustomerId(),'project_id'=>$destination==='project'?$id:null,'project_supplier_id'=>(int)$r['project_supplier_id'],'created_by'=>$this->users->getUser()?->getUID()??'system','created_at'=>$now];$this->db->beginTransaction();try{
   if($destination==='stock'){$q=$this->db->getQueryBuilder();$q->update('re_erp_materials')->set('stock_quantity',$q->createNamedParameter((float)$r['stock_quantity']+$quantity))->where($q->expr()->eq('id',$q->createNamedParameter((int)$r['material_id'])))->executeStatement();$this->insertRow('re_erp_stock_movements',$base+['movement_type'=>'in','quantity'=>$quantity,'note'=>$label,'unit_cost'=>$cost]);}
   else{$this->insertRow('re_erp_stock_movements',$base+['movement_type'=>'in','quantity'=>$quantity,'note'=>$label.' · Direktlieferung Projekt','unit_cost'=>$cost]);$this->insertRow('re_erp_stock_movements',$base+['movement_type'=>'out','quantity'=>-$quantity,'note'=>$label.' · Direktlieferung Projekt','unit_cost'=>$cost]);}
   $q=$this->db->getQueryBuilder();$q->update('re_erp_purchase_items')->set('received_qty',$q->createNamedParameter($received+$quantity))->set('updated_at',$q->createNamedParameter($now))->where($q->expr()->eq('id',$q->createNamedParameter($itemId)))->executeStatement();
   $psid=(int)$r['project_supplier_id'];$q=$this->db->getQueryBuilder();$q->select('ordered_qty','received_qty')->from('re_erp_purchase_items')->where($q->expr()->eq('project_supplier_id',$q->createNamedParameter($psid)));$all=$q->executeQuery()->fetchAll();$any=false;$complete=true;foreach($all as $x){$rq=(float)$x['received_qty'];$oq=(float)$x['ordered_qty'];if($rq>0)$any=true;if($rq+0.0001<$oq)$complete=false;}$status=$complete?'complete':($any?'partial':'open');$q=$this->db->getQueryBuilder();$q->update('re_erp_project_suppliers')->set('receipt_status',$q->createNamedParameter($status))->set('updated_at',$q->createNamedParameter($now))->where($q->expr()->eq('id',$q->createNamedParameter($psid)))->executeStatement();$this->db->commit();
  }catch(\Throwable $e){$this->db->rollBack();throw $e;}$this->activities->record('project',$id,'goods_received','Wareneingang gebucht',$r['material_name'].' · '.$quantity.' · '.($destination==='stock'?'Lager':'direkt Projekt'),$project->getCustomerId(),$id);return new RedirectResponse($this->url->linkToRoute('reinhardterp.page.projectDetail',['id'=>$id]).'#suppliers');
 }
 #[NoAdminRequired] public function deletePurchaseItem(int $id,int $itemId):RedirectResponse{$this->permissions->assertProjectManager();$project=$this->mapper->find($id);$q=$this->db->getQueryBuilder();$q->select('pi.received_qty')->from('re_erp_purchase_items','pi')->leftJoin('pi','re_erp_project_suppliers','ps',$q->expr()->eq('ps.id','pi.project_supplier_id'))->where($q->expr()->eq('pi.id',$q->createNamedParameter($itemId)))->andWhere($q->expr()->eq('ps.project_id',$q->createNamedParameter($id)));$r=$q->executeQuery()->fetch();if(!$r)throw new \InvalidArgumentException('Bestellposition nicht gefunden.');if((float)$r['received_qty']>0)throw new \InvalidArgumentException('Bereits belieferte Positionen können nicht gelöscht werden.');$q=$this->db->getQueryBuilder();$q->delete('re_erp_purchase_items')->where($q->expr()->eq('id',$q->createNamedParameter($itemId)))->executeStatement();return new RedirectResponse($this->url->linkToRoute('reinhardterp.page.projectDetail',['id'=>$id]).'#suppliers');}
 private function insertRow(string $table,array $data):void{$q=$this->db->getQueryBuilder();$q->insert($table);foreach($data as $k=>$v)$q->setValue($k,$q->createNamedParameter($v));$q->executeStatement();}
 #[NoAdminRequired] public function deleteSupplierCockpit(int $id,int $rowId):RedirectResponse{
  $this->permissions->assertProjectManager();$project=$this->mapper->find($id);$q=$this->db->getQueryBuilder();$q->select('received_qty')->from('re_erp_purchase_items')->where($q->expr()->eq('project_supplier_id',$q->createNamedParameter($rowId)));foreach($q->executeQuery()->fetchAll() as $pi){if((float)($pi['received_qty']??0)>0)throw new \InvalidArgumentException('Bestellungen mit gebuchtem Wareneingang können nicht entfernt werden.');}$q=$this->db->getQueryBuilder();$q->delete('re_erp_purchase_items')->where($q->expr()->eq('project_supplier_id',$q->createNamedParameter($rowId)))->executeStatement();$q=$this->db->getQueryBuilder();$q->delete('re_erp_project_suppliers')->where($q->expr()->eq('id',$q->createNamedParameter($rowId)))->andWhere($q->expr()->eq('project_id',$q->createNamedParameter($id)))->executeStatement();$this->activities->record('project',$id,'supplier_deleted','Lieferantenzeile entfernt','',$project->getCustomerId(),$id);return new RedirectResponse($this->url->linkToRoute('reinhardterp.page.projectDetail',['id'=>$id]).'#suppliers');
 }

 private function d(?string $v):?\DateTime{if($v===null||trim($v)==='')return null;$d=\DateTime::createFromFormat('!Y-m-d',$v);if($d===false)throw new \InvalidArgumentException('Ungültiges Datum.');return $d;}

 private function freezeCalculation(int $projectId):void{
  $q=$this->db->getQueryBuilder();$q->select('calc_locked_at')->from('re_erp_projects')->where($q->expr()->eq('id',$q->createNamedParameter($projectId)));if($q->executeQuery()->fetchOne())return;
  $value=0.0;$offerId=0;$q=$this->db->getQueryBuilder();$q->select('net_amount')->from('re_erp_orders')->where($q->expr()->eq('project_id',$q->createNamedParameter($projectId)))->orderBy('order_date','DESC')->addOrderBy('id','DESC')->setMaxResults(1);$value=(float)($q->executeQuery()->fetchOne()?:0);
  $q=$this->db->getQueryBuilder();$q->select('id','net_amount')->from('re_erp_offers')->where($q->expr()->eq('project_id',$q->createNamedParameter($projectId)))->orderBy('offer_date','DESC')->addOrderBy('id','DESC')->setMaxResults(1);$offer=$q->executeQuery()->fetch()?:[];$offerId=(int)($offer['id']??0);if($value<=0)$value=(float)($offer['net_amount']??0);
  $hours=0.0;$material=0.0;$external=0.0;if($offerId>0){$q=$this->db->getQueryBuilder();$q->selectAlias($q->createFunction('SUM(planned_hours)'),'h')->addSelect($q->createFunction('SUM(planned_material_cost) AS m'))->addSelect($q->createFunction('SUM(planned_external_cost) AS e'))->from('re_erp_offer_items')->where($q->expr()->eq('offer_id',$q->createNamedParameter($offerId)))->andWhere($q->expr()->eq('is_alternative',$q->createNamedParameter(0)));$r=$q->executeQuery()->fetch()?:[];$hours=(float)($r['h']??0);$material=(float)($r['m']??0);$external=(float)($r['e']??0);}
  $u=$this->db->getQueryBuilder();$u->update('re_erp_projects')->set('calc_value_net',$u->createNamedParameter($value))->set('calc_hours',$u->createNamedParameter($hours))->set('calc_material',$u->createNamedParameter($material))->set('calc_external',$u->createNamedParameter($external))->set('calc_locked_at',$u->createNamedParameter(date('Y-m-d H:i:s')))->where($u->expr()->eq('id',$u->createNamedParameter($projectId)))->executeStatement();
 }
 private function n(?string $v):?string{if($v===null)return null;$v=trim($v);return $v===''?null:$v;}
